template<class F>void rejects(F f){bool rejected=false;try{f();}catch(...){rejected=true;}CHECK(rejected);}
static unsigned wordIndex(const Geometry& g,const QString& word){auto words=g->data["words"].toArray();for(int i=0;i<words.size();++i){auto s=select(g,unsigned(i),unsigned(i),1);if(s&&s->data["normalized"].toString()==word)return unsigned(i);}throw std::runtime_error("fixture-word-missing");}
static std::pair<double,double> center(const Geometry& g,unsigned word){auto w=g->data["words"].toArray()[int(word)].toArray();auto q=g->data["chars"].toArray()[w[0].toInt()].toObject()["quad"].toArray();double x=0,y=0;for(int i=0;i<8;i+=2){x+=q[i].toDouble()/4;y+=q[i+1].toDouble()/4;}auto m=g->data["transform"].toArray();return {m[0].toDouble()*x+m[2].toDouble()*y+m[4].toDouble(),m[1].toDouble()*x+m[3].toDouble()*y+m[5].toDouble()};}
static Geometry compoundGeometry(const Geometry& original,const QByteArray& binding,const QString& text){
 auto data=original->data;QJsonArray chars,words,lines;int line=0,start=0,x=100;
 for(int i=0;i<text.size();++i){if(text[i]=='\n'){lines.append(QJsonArray{start,i,0});start=i+1;++line;x=100;continue;}const int y=300+line*40;chars.append(QJsonObject{{"offset",i},{"text",text.mid(i,1)},{"u",int(text[i].unicode())},{"line",line},{"block",0},{"quad",QJsonArray{x,y,x+12,y,x,y+24,x+12,y+24}}});x+=14;}
 lines.append(QJsonArray{start,int(text.size()),0});for(int i=0;i<chars.size();){if(!QChar::isLetter(uint(chars[i].toObject()["u"].toInt()))){++i;continue;}int begin=i;while(i<chars.size()&&QChar::isLetter(uint(chars[i].toObject()["u"].toInt())))++i;words.append(QJsonArray{begin,i});}
 data["text"]=text;data["chars"]=chars;data["words"]=words;data["lines"]=lines;data["blocks"]=QJsonArray{QJsonArray{0,int(text.size())}};data["transform"]=QJsonArray{1,0,0,1,0,0};data["transformId"]=QString(64,'c');data.remove("visibleSourceRect");data.remove("viewId");return decodeGeometry(data,binding);
}
static input_event ev(int type,int code,int value){input_event e{};e.type=type;e.code=code;e.value=value;return e;}
static void markerStroke(ux::Shell& shell,Canvas& canvas,int x,int y,bool erase){auto engine=std::make_unique<spike::Engine>(spike::Transform{{0,1619},{0,2159},1620,2160,0,false},shell.ink(),canvas);spike::FrameAssembler a;spike::Scheduler scheduler;spike::SessionStats stats;std::array down={ev(EV_KEY,BTN_TOOL_PEN,!erase),ev(EV_KEY,BTN_TOOL_RUBBER,erase),ev(EV_ABS,ABS_X,x),ev(EV_ABS,ABS_Y,y),ev(EV_KEY,BTN_TOUCH,1),ev(EV_SYN,SYN_REPORT,0)};CHECK(spike::consumeEvents(down,a,*engine,scheduler,stats,1,nullptr,&shell));auto menu=shell.semanticVisual().menu;CHECK(!shell.finger(menu.x0+20,menu.y0+20,false));CHECK(!shell.finger(x,y,true));std::array move={ev(EV_ABS,ABS_X,x+30),ev(EV_SYN,SYN_REPORT,0)};CHECK(spike::consumeEvents(move,a,*engine,scheduler,stats,8000001,nullptr,&shell));std::array up={ev(EV_KEY,BTN_TOUCH,0),ev(EV_SYN,SYN_REPORT,0)};CHECK(spike::consumeEvents(up,a,*engine,scheduler,stats,16000001,nullptr,&shell));CHECK(stats.samples==3&&stats.contacts==1&&stats.released==1);}
